import pandas as pd, numpy as np
from sklearn.model_selection import KFold
from lightgbm import LGBMRegressor
import statsmodels.api as sm
df=pd.read_csv('data.csv'); df['dd']=df['dY']-df['dY_placebo']; df['pregmv']=np.exp(df.log_pre_gmv)
feats=['log_hist_days','region','log_pre_gmv','orders','cat_share','tenure','tier']
X=df[feats].astype({'region':int,'tier':int})
def cf(X,y,seed=7,nest=400):
    p=np.zeros(len(y)); kf=KFold(5,shuffle=True,random_state=seed)
    for tr,te in kf.split(X):
        m=LGBMRegressor(n_estimators=nest,learning_rate=0.05,num_leaves=31,min_child_samples=40,subsample=0.8,subsample_freq=1,colsample_bytree=0.8,random_state=seed,verbose=-1).fit(X.iloc[tr],np.asarray(y)[tr]); p[te]=m.predict(X.iloc[te])
    return p
T=df['D'].values-cf(X,df['D']); R=df['dd'].values-cf(X,df['dd'])
specs={'const':np.ones(len(df)),'log_pre_gmv':df.log_pre_gmv.values,'pregmv':df.pregmv.values,
       'sqrt_pregmv':np.sqrt(df.pregmv.values),'tier':df.tier.values.astype(float),
       'log+tier':None,'orders':df.orders.values.astype(float)}
best=None
for k,v in specs.items():
    if k=='log+tier':
        Z=np.c_[T, T*df.log_pre_gmv.values, T*df.tier.values.astype(float)]
        tau_i=None
    else:
        Z=np.c_[T, T*v] if k!='const' else T.reshape(-1,1)
    r=sm.OLS(R,Z).fit(cov_type='HC1'); loss=np.mean((R-r.fittedvalues)**2)
    if k=='const': ate=r.params[0]; print(f'{k:12s} ATE={ate:+.4f}  R-loss={loss:.5f}')
    else:
        if k=='log+tier': ate=r.params[1]+r.params[2]*df.log_pre_gmv.mean()+r.params[3]*df.tier.mean()
        elif k=='log_pre_gmv': ate=r.params[0]+r.params[1]*df.log_pre_gmv.mean()
        elif k=='tier': ate=r.params[0]+r.params[1]*df.tier.mean()
        elif k=='orders': ate=r.params[0]+r.params[1]*df.orders.mean()
        else: ate=r.params[0]+r.params[1]*v.mean()
        print(f'{k:12s} ATE={ate:+.4f}  R-loss={loss:.5f}  coefs={np.round(r.params,5).tolist()} se={np.round(r.bse,5).tolist()}')
# tier-specific
Z=np.c_[[T*(df.tier.values==t) for t in range(4)]].T
r=sm.OLS(R,Z).fit(cov_type='HC1')
print('by tier:',np.round(r.params,4).tolist(),np.round(r.bse,4).tolist())
w=np.array([(df.tier==t).mean() for t in range(4)]); print('plain ATE (tier weights):',round((r.params*w).sum(),4))
